import {T,Kit} from './core.js?v=75';
import {HOTEL_DRIVE as D} from './hotel-drive-data.js?v=75';
import {surfacePerimeter,edgeSurface} from './surface-seams.js?v=75';
import {subtractGarageFootprint} from './garage-site.js?v=91';
export {HOTEL_DRIVE} from './hotel-drive-data.js?v=75';
function inRing(x,z,r){let hit=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],b=r[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
export function hotelRoadContains(x,z){return D.road.polygons.some(p=>inRing(x,z,p.outer)&&!p.holes.some(r=>inRing(x,z,r)));}
export function hotelDriveOverlaps(box){if(box.max.x<D.bounds.minX||box.min.x>D.bounds.maxX||box.max.z<D.bounds.minZ||box.min.z>D.bounds.maxZ)return false;const pad=.25;for(let x=box.min.x-pad;x<=box.max.x+pad;x+=Math.max(.4,(box.max.x-box.min.x)/5))for(let z=box.min.z-pad;z<=box.max.z+pad;z+=Math.max(.4,(box.max.z-box.min.z)/5))if(hotelRoadContains(x,z))return true;return false;}
function surface(k,m,name,data,height,extras={}){const g=new T.BufferGeometry(),p=data.vertices.flatMap(([x,z])=>[x,height(x,z),z]);g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(data.vertices.flatMap(([x,z])=>[x/2,z/2]),2));const pos=g.attributes.position,indices=[];for(let i=0;i<data.indices.length;i+=3){let [a,b,c]=data.indices.slice(i,i+3);const area=(pos.getZ(b)-pos.getZ(a))*(pos.getX(c)-pos.getX(a))-(pos.getX(b)-pos.getX(a))*(pos.getZ(c)-pos.getZ(a));if(Math.abs(area)<1e-9)continue;if(area<0)[b,c]=[c,b];indices.push(a,b,c);}g.setIndex(indices);g.computeVertexNormals();const mesh=k.mesh(g,m,name);mesh.castShadow=false;mesh.userData={hotelDrive:true,...extras};return mesh;}
function line(k,m,points,width,name,y=.002){const p=[],uv=[],ix=[];for(let i=0;i<points.length;i++){const a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],dx=b[0]-a[0],dz=b[1]-a[1],l=Math.hypot(dx,dz);for(const sign of [-1,1]){const x=points[i][0]-dz/l*width/2*sign,z=points[i][1]+dx/l*width/2*sign;p.push(x,y,z);uv.push(x/2,z/2);}if(i){const n=(i-1)*2;ix.push(n,n+1,n+2,n+1,n+3,n+2);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();const mesh=k.mesh(g,m,name);mesh.castShadow=false;mesh.userData={hotelDriveMarking:true};return mesh;}
export function buildHotelDrive(group,m){const k=new Kit(group);surface(k,m.asphalt,'Hauptstraße mit eigenständiger Hotelvorfahrt',D.road,()=>-.005,{hotelRoad:true,mainWidth:D.mainWidth,approachWidth:D.driveWidth,shiftMeters:D.shiftMeters,singleAsphaltUnion:true,separateApproachAndExit:true});const cap=[],curbIndices=[];for(let i=0;i<D.curb.indices.length;i+=3){const ids=D.curb.indices.slice(i,i+3);(ids.every(j=>D.curb.vertices[j][0]<D.bounds.minX+.01&&D.curb.vertices[j][1]<34)?cap:curbIndices).push(...ids);}surface(k,m.ivory,'Sauber vereinigte Bordsteine der Hotelvorfahrt',{...D.curb,indices:curbIndices},()=>.12,{hotelDriveCurb:true});if(cap.length)surface(k,m.asphalt,'Bündiger Asphalt statt überhöhtem Querbalken am Straßenanschluss',{...D.curb,indices:cap},()=>-.005,{hotelRoadJoinRepair:true,removedCurbCap:true});surface(k,m.cobbles,'An die verschobene Hauptstraße angepasster Gehweg',D.walk,()=>.12,{hotelDriveWalk:true});
 // Closed curb skirts reach below the real meadow. No suspended curb plates.
 const p=[],uv=[],ix=[];for(const poly of D.curb.polygons)for(const ring of [poly.outer,...poly.holes])for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length];if(a[0]<D.bounds.minX+.01&&b[0]<D.bounds.minX+.01&&a[1]<34&&b[1]<34)continue;const n=p.length/3;p.push(a[0],.12,a[1],a[0],-.28,a[1],b[0],.12,b[1],b[0],-.28,b[1]);uv.push(0,0,0,1,1,0,1,1);ix.push(n,n+1,n+2,n+2,n+1,n+3);}const skirt=new T.BufferGeometry();skirt.setAttribute('position',new T.Float32BufferAttribute(p,3));skirt.setAttribute('uv',new T.Float32BufferAttribute(uv,2));skirt.setIndex(ix);skirt.computeVertexNormals();const edge=m.ivory.clone();edge.name='Geschlossene Bordsteine der Hotelvorfahrt';edge.side=T.DoubleSide;k.mesh(skirt,edge,'Geschlossene Straßenrandanschlüsse bis ins Gelände');
 for(let i=3;i<D.main.length-6;i+=12)line(k,m.roadPaint,D.main.slice(i,i+7),.12,'Gleichmäßige Mittelmarkierung auf der verschobenen Straße');
 for(const x of [-25,25]){const s=new T.Shape();s.moveTo(x+.70,35.56);for(const q of [[x-.05,35.56],[x-.05,35.34],[x-.78,35.7],[x-.05,36.06],[x-.05,35.84],[x+.70,35.84]])s.lineTo(...q);s.closePath();const g=new T.ShapeGeometry(s),pos=g.attributes.position;for(let i=0;i<pos.count;i++)pos.setXYZ(i,pos.getX(i),.004,pos.getY(i));const idx=g.index;for(let i=0;i<idx.count;i+=3){const a=new T.Vector3().fromBufferAttribute(pos,idx.getX(i)),b=new T.Vector3().fromBufferAttribute(pos,idx.getX(i+1)),c=new T.Vector3().fromBufferAttribute(pos,idx.getX(i+2));if(b.sub(a).cross(c.sub(a)).y<0){const q=idx.getX(i+1);idx.setX(i+1,idx.getX(i+2));idx.setX(i+2,q);}}g.computeVertexNormals();const o=k.mesh(g,m.roadPaint,'Dezenter Richtungspfeil der Hotelvorfahrt');o.userData={hotelDriveDirection:'west'};}
 const marker=new T.Object3D();marker.name='Getrennte Hotelzufahrt und Hotelabfahrt';marker.userData={hotelDrivePlan:true,revision:57,mainCenterline:D.main,entry:D.entry,exit:D.exit,drive:D.drive,mainWidth:D.mainWidth,driveWidth:D.driveWidth,minimumRadii:D.minimumRadii,vipBayPreserved:true,garageApproachSeparated:true};group.add(marker);k.finish();
}
export function reconstructHotelVerge(scene,m){scene.updateMatrixWorld(true);const b=D.bounds,terrain=[],remove=[];scene.traverse(o=>{if(o.isMesh&&!o.isInstancedMesh&&o.material===m.meadow&&!o.userData.hotelDrive){o.geometry.computeBoundingBox();const box=o.geometry.boundingBox.clone().applyMatrix4(o.matrixWorld);if(box.min.x<b.maxX&&box.max.x>b.minX&&box.min.z<b.maxZ&&box.max.z>b.minZ)terrain.push(o);}});
 const ray=new T.Raycaster(),height=(x,z)=>{const distance=Math.min(x-b.minX,b.maxX-x,z-b.minZ,b.maxZ-z),t=Math.max(0,Math.min(1,distance/2.5)),w=t*t*(3-2*t);if(w>=1&&!(x>=20.67-1e-5&&x<=21.47&&z>=28.4-1e-5&&z<=33.6+1e-5))return -.18;ray.set(new T.Vector3(x,15,z),new T.Vector3(0,-1,0));const source=ray.intersectObjects(terrain,false)[0]?.point.y??-.18;const base=source*(1-w)-.18*w;if(x>=20.67-1e-5&&x<=21.47&&z>=28.4-1e-5&&z<=33.6+1e-5){const t=Math.max(0,Math.min(1,(x-20.67)/.8)),blend=t*t*(3-2*t);return -.005*(1-blend)+base*blend;}return base;};
 const group=new T.Group();group.name='Neu modellierter Grünraum zwischen Hauptstraße und Hotel';scene.add(group);const k=new Kit(group),grass=surface(k,m.meadow,'Geschlossene Wiesenflächen um die eigenständige Hotelvorfahrt',D.grass,height,{hotelDriveTerrain:true,closed:true});const uv=grass.geometry.attributes.uv;D.grass.vertices.forEach(([x,z],i)=>uv.setXY(i,x/4,z/4));
 for(const o of terrain){const world=o.geometry.clone().applyMatrix4(o.matrixWorld),cut=subtractGarageFootprint(world,b);o.geometry=cut.applyMatrix4(o.matrixWorld.clone().invert());o.userData.hotelDriveGroundCut=true;if(!cut.attributes.position.count)remove.push(o);}remove.forEach(o=>o.removeFromParent());k.finish();return grass;
}

export function closeHotelPavingSeams(scene,m){scene.updateMatrixWorld(true);const ground=[],walk=[];scene.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;if(o.material===m.meadow)ground.push(o);if(o.userData.hotelDriveWalk)walk.push(o);});const join={minX:D.bounds.minX-.10,maxX:D.bounds.minX+.01,minZ:28.4,maxZ:39.7};scene.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;if(o.userData.villageTrafficSurface==='road'){o.geometry=subtractGarageFootprint(o.geometry.clone().applyMatrix4(o.matrixWorld),{...D.bounds,minX:join.minX}).applyMatrix4(o.matrixWorld.clone().invert());o.userData.hotelRoadJoinRepair=true;}else if(o.userData.hotelRoad||o.userData.removedCurbCap){o.geometry=subtractGarageFootprint(o.geometry.clone().applyMatrix4(o.matrixWorld),join).applyMatrix4(o.matrixWorld.clone().invert());}});const empty=[];scene.traverse(o=>{if(o.isMesh&&!o.isInstancedMesh&&o.geometry.attributes.position.count===0)empty.push(o);});empty.forEach(o=>o.removeFromParent());const joinGroup=new T.Group();scene.add(joinGroup);surface(new Kit(joinGroup),m.asphalt,'Durchgehend geschlossener Asphaltanschluss zwischen Dorf und Hotel',{vertices:[[join.minX,join.minZ],[join.minX,join.maxZ],[join.maxX,join.maxZ],[join.maxX,join.minZ]],indices:[0,1,2,0,2,3]},()=>-.005,{hotelRoadJoinRepair:true,closed:true,removedCurbCap:true});const onBoundary=(a,b)=>[['x',D.bounds.minX],['x',D.bounds.maxX],['z',D.bounds.minZ],['z',D.bounds.maxZ]].some(([axis,v])=>Math.abs(a[axis]-v)<.0001&&Math.abs(b[axis]-v)<.0001);const soilEdges=ground.flatMap(surfacePerimeter).filter(({a,b})=>onBoundary(a,b)&&[a,b].every(p=>p.x>=D.bounds.minX-.001&&p.x<=D.bounds.maxX+.001&&p.z>=D.bounds.minZ-.001&&p.z<=D.bounds.maxZ+.001));edgeSurface(scene,m.meadow,'Geschlossener Übergang zwischen bestehender und reparierter Hotelwiese',soilEdges,p=>Math.min(p.y-.04,-.5),{hotelTerrainSeamRepair:true,revision:58});const substrate=new T.PlaneGeometry(11,2.51);substrate.rotateX(-Math.PI/2);substrate.translate(D.bounds.minX,-.27,40.955);const sp=substrate.attributes.position,suv=substrate.attributes.uv;for(let i=0;i<sp.count;i++)suv.setXY(i,sp.getX(i)/4,sp.getZ(i)/4);const base=new T.Mesh(substrate,m.meadow);base.name='Rekonstruierter geschlossener Boden unter dem Gehweganschluss';base.userData={hotelDrive:true,hotelPavingSubstrateRepair:true,revision:58};base.receiveShadow=true;scene.add(base);const ray=new T.Raycaster();return edgeSurface(scene,m.cobbles,'Geschlossener äußerer Gehwegrand der Hotelvorfahrt',walk.flatMap(surfacePerimeter),p=>{ray.set(new T.Vector3(p.x,15,p.z),new T.Vector3(0,-1,0));return Math.min(p.y-.04,(ray.intersectObjects(ground,false)[0]?.point.y??-.28)-.10);},{hotelWalkSeamRepair:true,revision:58});}
